// 並列の署名・frame符号化が単件追記と同一の連番・署名連鎖を返すことを検査する。
package evidence

import (
	"crypto/ed25519"
	"crypto/rand"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"oimobbs/internal/domain"
	"oimobbs/internal/store"
)

func TestRequiredParallelMatchesSingleAppends(t *testing.T) {
	_, key, _ := ed25519.GenerateKey(rand.Reader)
	owner, seed := domain.NewID(), domain.NewID()
	build := func(src Source) ([]byte, error) {
		return json.Marshal(testPayload{src.Owner, domain.U64(src.Subkey), domain.U64(src.Seq), strings.Repeat("payload-", 256)})
	}
	open := func() *Journal {
		t.Helper()
		root := t.TempDir()
		if err := os.Chmod(root, 0700); err != nil {
			t.Fatal(err)
		}
		j, err := OpenJournal(filepath.Join(root, "20260928"), owner, 20260928, 10, key, testValidator)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { _ = j.Close() })
		if _, result := j.Append(seed, "attempt", 1, build); result.Status != store.Durable {
			t.Fatal(result)
		}
		return j
	}
	serial, parallel := open(), open()
	var requests []AppendRequest
	var expected []Event
	for range 64 {
		id := domain.NewID()
		requests = append(requests, AppendRequest{id, "attempt", 1, build})
		event, result := serial.Append(id, "attempt", 1, build)
		if result.Status != store.Durable {
			t.Fatal(result)
		}
		expected = append(expected, event)
	}
	before := parallel.CommitStats()
	actual, result := parallel.AppendBatch(requests)
	if result.Status != store.Durable || !reflect.DeepEqual(actual, expected) || parallel.CommitStats().Syncs-before.Syncs != 1 {
		t.Fatal("batch altered signature chain or Sync boundary", result)
	}
	if !reflect.DeepEqual(serial.Entries(), parallel.Entries()) {
		t.Fatal("batch payloads differ")
	}
}

