// 制御frameの独立した解析だけを並列化し、状態適用・検証callback・保存の順序を変えない。
package store

import "oimobbs/internal/workparallel"

type preparedControlOperation struct {
	firstSeq uint64
	op       ControlOperation
}

// prepareControlFrames は元の順で最初のエラーを返し、全候補の8MiB予算を確保前に検査する。
// 返却操作は呼出元専用。ControlLogの状態・validator・writerには触れない。
func prepareControlFrames(frames [][]byte) ([]preparedControlOperation, []Mutation, error) {
	total, count := 0, len(frames)
	for i, frame := range frames {
		if len(frames) > 1 && len(frame) > (8<<20)-total {
			count = i
			break
		}
		total += len(frame)
	}
	decoded := make([]preparedControlOperation, count)
	errors := make([]error, count)
	decode := func(i int) {
		frame, err := decodeFrameView(frames[i])
		if err != nil || len(frame.Records) != 1 {
			errors[i] = ErrCorrupt
			return
		}
		op, err := decodeControlOperation(frame)
		if err == nil && (len(op.Mutations) < 1 || len(op.Mutations) > 256) {
			err = ErrCorrupt
		}
		decoded[i], errors[i] = preparedControlOperation{frame.FirstSeq, op}, err
	}
	if count >= 8 && total >= 16<<10 {
		workparallel.For(count, decode)
	} else {
		for i := range decoded {
			decode(i)
		}
	}
	var mutations []Mutation
	for i, prepared := range decoded {
		if errors[i] != nil {
			return nil, nil, errors[i]
		}
		mutations = append(mutations, prepared.op.Mutations...)
	}
	if count != len(frames) {
		return nil, nil, ErrCorrupt
	}
	return decoded, mutations, nil
}

