func referencePrepareControl(frames [][]byte) ([]preparedControlOperation, []Mutation, error) {
	var decoded []preparedControlOperation
	var mutations []Mutation
	total := 0
	for _, raw := range frames {
		if len(frames) > 1 && len(raw) > (8<<20)-total {
			return nil, nil, ErrCorrupt
		}
		total += len(raw)
		frame, err := decodeFrameView(raw)
		if err != nil || len(frame.Records) != 1 {
			return nil, nil, ErrCorrupt
		}
		op, err := decodeControlOperation(frame)
		if err != nil {
			return nil, nil, err
		}
		if len(op.Mutations) < 1 || len(op.Mutations) > 256 {
			return nil, nil, ErrCorrupt
		}
		decoded = append(decoded, preparedControlOperation{frame.FirstSeq, op})
		mutations = append(mutations, op.Mutations...)
	}
	return decoded, mutations, nil
}

func FuzzControlBatchPreparationMatchesSequential(f *testing.F) {
	op := ControlOperation{Schema: 1, Seq: 1, Actor: domain.Actor{Kind: "system", Reason: "test"}, Mutations: []Mutation{{Collection: "board", Key: "state", Value: json.RawMessage(`{"v":"` + strings.Repeat("x", 2048) + `"}`)}}, Result: ControlResult{Code: "updated", Targets: []string{}}}
	raw, _ := json.Marshal(op)
	valid, _ := EncodeFrame(Frame{FirstSeq: 1, Records: []Record{{ID: domain.ID{1}, JSON: raw}}})
	f.Add(valid, byte(0))
	f.Add([]byte("invalid frame"), byte(15))
	f.Fuzz(func(t *testing.T, raw []byte, at byte) {
		if len(raw) > 8192 {
			t.Skip()
		}
		frames := make([][]byte, 16)
		for i := range frames {
			frames[i] = valid
		}
		frames[int(at)%len(frames)] = raw
		want, wm, we := referencePrepareControl(frames)
		got, gm, ge := prepareControlFrames(frames)
		if (we == nil) != (ge == nil) || we != nil && we.Error() != ge.Error() || !reflect.DeepEqual(want, got) || !reflect.DeepEqual(wm, gm) {
			t.Fatal("parallel preparation differs", we, ge)
		}
	})
}

func TestControlPreparationKeepsPrefixErrorBeforeBudget(t *testing.T) {
	invalid, err := EncodeFrame(Frame{FirstSeq: 1, Records: []Record{{ID: domain.ID{1}, JSON: []byte(`{}`)}}})
	if err != nil {
		t.Fatal(err)
	}
	frames := [][]byte{invalid, make([]byte, 8<<20)}
	_, _, want := referencePrepareControl(frames)
	_, _, got := prepareControlFrames(frames)
	if want == nil || got == nil || want.Error() != got.Error() {
		t.Fatal("later budget error hid first schema error", want, got)
	}
}

