// Package workparallel は独立した準備処理をCPU数と共有補助枠の範囲内で並列実行する。
package workparallel

import (
	"runtime"
	"sync"
)

// 板やjournalの数によらず補助goroutineは全体で最大8本。枠待ちはせず呼出元へ戻す。
var helpers = make(chan struct{}, 8)

// For は各indexを一度処理し、全処理の終了後に返る。index 0は常に呼出元が実行する。
// runはindex間で独立した結果だけを更新し、共有map・採番・公開状態を変更してはならない。
func For(n int, run func(int)) {
	workers := 1
	limit := min(n, runtime.GOMAXPROCS(0), cap(helpers)+1)
acquire:
	for workers < limit {
		select {
		case helpers <- struct{}{}:
			workers++
		default:
			break acquire
		}
	}
	var group sync.WaitGroup
	defer group.Wait()
	for worker := 1; worker < workers; worker++ {
		group.Go(func() {
			defer func() { <-helpers }()
			for i := worker; i < n; i += workers {
				run(i)
			}
		})
	}
	for i := 0; i < n; i += workers {
		run(i)
	}
}

