var/posting-parallel-20261018/rejected-c.internal/bootstrap/posting_preparation_t:
// HTTPの純粋な準備を並行しても、板の状態を所有列で改めて確認することを検査する。
package bootstrap

import (
	"context"
	"net/url"
	"strings"
	"sync"
	"testing"
	"time"

	"oimobbs/internal/postcapture"
)

func TestHTTPPreparationDoesNotHoldBoardAndRechecksStop(t *testing.T) {
	for _, mode := range []string{"prepare", "stopped", "closed"} {
		t.Run(mode, func(t *testing.T) {
			cfg := testConfig(t)
			report, err := Initialize(cfg, "並行準備試験")
			if err != nil {
				t.Fatal(err)
			}
			entered, release := make(chan struct{}), make(chan struct{})
			var enteredOnce, releaseOnce sync.Once
			unblock := func() { releaseOnce.Do(func() { close(release) }) }
			defer unblock()
			repo, err := OpenPostingRepository(cfg, func(raw []byte) error {
				if strings.Contains(string(raw), `"schema":"http-observation-v1"`) {
					enteredOnce.Do(func() { close(entered) })
					<-release
				}
				return postcapture.Validate(raw)
			})
			if err != nil {
				t.Fatal(err)
			}
			defer repo.Close()
			info, err := repo.CreateBoard(t.Context(), "news", "ニュース")
			if err != nil {
				t.Fatal(err)
			}
			server := formServer(t, repo, report.SiteID, info.ID)
			defer server.Close()
			finished := make(chan formResult, 1)
			go func() {
				result, err := sendFormOnce(server, url.Values{"bbs": {"news"}, "subject": {"題"}, "MESSAGE": {"本文"}}, "")
				if err != nil {
					t.Error(err)
				}
				finished <- result
			}()
			select {
			case <-entered:
			case <-time.After(5 * time.Second):
				unblock()
				t.Fatal("HTTP preparation did not start")
			}
			owned := make(chan struct{})
			go func() {
				if mode == "closed" {
					if err := repo.Close(); err != nil {
						t.Error(err)
					}
					close(owned)
					return
				}
				_, err := repo.posting[info.ID].worker.Submit(context.Background(), func() (any, error) {
					repo.posting[info.ID].stopped = mode == "stopped"
					close(owned)
					return nil, nil
				})
				if err != nil {
					t.Error(err)
				}
			}()
			select {
			case <-owned:
			case <-time.After(5 * time.Second):
				unblock()
				t.Fatal("HTTP preparation held board ownership")
			}
			unblock()
			result := <-finished
			if result.Accepted || (result.Confirmation != nil) != (mode == "prepare") {
				t.Fatal("board state was not rechecked after preparation", result)
			}
		})
	}
}
